-- Carga 14 de 26 de la herramienta arbitros-cr. La arma herramientas/arbitros-cr.py: no se edita a mano.
-- Lee las respuestas 18165 a 18204 del buscador de chess-results (net._http_response).
with r as (select id, substr(content, strpos(content, '<table class="CRs2"')) t from net._http_response
  where id between 18165 and 18204 and strpos(content, '<table class="CRs2"') > 0),
filas as (select f from r, regexp_split_to_table(substr(t, 1, strpos(t, '</table>')), '<tr class="CR') f where f ~ '^n?g[12]">'),
celdas as (select regexp_split_to_array(f, '</t[dh]>') c from filas),
t as (select distinct on (btrim(regexp_replace(c[19], '<[^>]+>', '', 'g'))::int) btrim(regexp_replace(c[19], '<[^>]+>', '', 'g'))::int clave, c from celdas
  where btrim(regexp_replace(c[19], '<[^>]+>', '', 'g')) ~ '^\d+$')
insert into public.arbitros_cr_cr (clave, nombre, inicio, fin, lugar, control, rondas, jugadores, pais)
select clave, coalesce(nullif(btrim(regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce((select string_agg(case when m[1] is not null then case when m[1]::int between 32 and 8999 then chr(m[1]::int) else '' end when m[2] is not null then '' else m[3] end, '' order by o) from regexp_matches(regexp_replace(c[2], '<[^>]+>', '', 'g'), '&#(\d+);|&#x([0-9A-Fa-f]+);|([^&]+|&)', 'g') with ordinality r(m, o)), ''), '&quot;', '"'), '&#39;', ''''), '&uuml;', 'ü'), '&Ouml;', 'Ö'), '&copy;', '©'), '&lt;', '<'), '&gt;', '>'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), '\s+', ' ', 'g')), ''), '(sin nombre)'),
  replace(btrim(regexp_replace(c[6], '<[^>]+>', '', 'g')), '/', '-')::date,
  nullif(replace(btrim(regexp_replace(c[7], '<[^>]+>', '', 'g')), '/', '-'), '')::date,
  left(btrim(regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce((select string_agg(case when m[1] is not null then case when m[1]::int between 32 and 8999 then chr(m[1]::int) else '' end when m[2] is not null then '' else m[3] end, '' order by o) from regexp_matches(regexp_replace(c[13], '<[^>]+>', '', 'g'), '&#(\d+);|&#x([0-9A-Fa-f]+);|([^&]+|&)', 'g') with ordinality r(m, o)), ''), '&quot;', '"'), '&#39;', ''''), '&uuml;', 'ü'), '&Ouml;', 'Ö'), '&copy;', '©'), '&lt;', '<'), '&gt;', '>'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), '\s+', ' ', 'g')), 200), left(btrim(regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce((select string_agg(case when m[1] is not null then case when m[1]::int between 32 and 8999 then chr(m[1]::int) else '' end when m[2] is not null then '' else m[3] end, '' order by o) from regexp_matches(regexp_replace(c[14], '<[^>]+>', '', 'g'), '&#(\d+);|&#x([0-9A-Fa-f]+);|([^&]+|&)', 'g') with ordinality r(m, o)), ''), '&quot;', '"'), '&#39;', ''''), '&uuml;', 'ü'), '&Ouml;', 'Ö'), '&copy;', '©'), '&lt;', '<'), '&gt;', '>'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), '\s+', ' ', 'g')), 200),
  coalesce(nullif(btrim(regexp_replace(c[17], '<[^>]+>', '', 'g')), '')::smallint, 0),
  coalesce(nullif(btrim(regexp_replace(c[18], '<[^>]+>', '', 'g')), '')::int, 0),
  coalesce(substring(btrim(regexp_replace(c[3], '<[^>]+>', '', 'g')) from '^[A-Z]{3}$'), 'CRC')
from t where clave = any('{18367,51625,106653,107376,120059,144401,144402,144720,144721,144740,144741,178016,179322,179406,186484,186485,186784,186785,190721,190722,191145,191146,218432,225644,229140,229149,229150,230679,231096,231097,231269,231270,233423,234522,235109,239435,240229,240230,240527,240528,240672,240734,240736,256088,256089,256090,265649,270573,270726,272992,273790,306061,317426,317427,319467,319468,323007,323555,367775,370016,399595,399596,446183,447139,486699,486702,486703,489491,523782,531197,531401,531552,531777,558411,558425,561541,561542,561543,561544,561545,561546,561547,561548,586435,586436,586437,586438,593585,613560,622352,647371,647372,647373,647375,647376,647379,647380,647382,647383,647384,647385,648627,648637,670634,670635,670827,671087,671279,671427,671449,671492,695089,695091,695093,695094,695096,695097,695098,699279,699661,719756,719757,774265,780818,780820,809135,809139,821436,835280,835924,918851,918852,932941,978267,978268,978270,979210,979213,979215,979217,979245,982361,982362,982405,982410,982939,982951,982955,982956,983259,983284,1029178,1074690,1074691,1074692,1074693,1075774,1075920,1075940,1092671,1092674,1133118,1167290,1192895,1192897,1212209,1223023,1226467,1226473,1228839,1228852,1241286,1244430,1245594,1245595,1245596,1245598,1250817,1250832,1252290,1253439,1253491,1277870,1277871,1277872,1277874,1435703,1439074,1440417,1442227,1453992,1453993,1453995,1453996,1455394,1455395,1455397,1455398,1455399,1455404,1455640,1455641,1458766,1460953,1492505,1492542,1494407,1494421,1495355,1495402,1507998,1508003,1513883,1513884,1513885}'::int[])
on conflict (clave) do update set nombre = excluded.nombre, inicio = excluded.inicio, fin = excluded.fin, lugar = excluded.lugar,
  control = excluded.control, rondas = excluded.rondas, jugadores = excluded.jugadores, pais = excluded.pais;
